// Le domaine définit l'abstraction (le port)
interface NotificationPort {
    void notify(String userId, String message);
}

// Le détail technique implémente le port
class EmailAdapter implements NotificationPort { /* ... */ }

// Le use case dépend de l'abstraction, jamais de l'email
class EnrollLearner {
    private final NotificationPort notifier;
    EnrollLearner(NotificationPort notifier) { this.notifier = notifier; }
}

// DIP : le use case dépend d'une abstraction (port), pas d'un détail
interface UserRepository { Optional<User> findById(UUID id); }

class GetUser {
    private final UserRepository repo;      // abstraction
    GetUser(UserRepository repo) {           // DI : on FOURNIT la dépendance
        this.repo = repo;
    }
}

// Injection manuelle (sans conteneur)  -  DI sans IoC container :
var useCase = new GetUser(new PostgresUserRepository(dataSource));

// Avec un IoC container (Spring) : le conteneur câble tout seul
// @Component sur PostgresUserRepository, constructeur injecté automatiquement.

class Account {
    // précondition : amount > 0 ; postcondition : balance diminue de amount
    void withdraw(int amount) { /* accepte tout montant positif */ }
}

class SavingsAccount extends Account {
    @Override
    void withdraw(int amount) {
        // ❌ RENFORCE la précondition : refuse ce que le parent acceptait
        if (amount > 500)
            throw new IllegalArgumentException("retrait plafonné à 500");
        // ...
    }
}

// Le client, écrit pour Account, casse quand on lui passe un SavingsAccount :
void payout(Account a) { a.withdraw(1000); }  // valide pour Account, explose pour Savings
// La hiérarchie compile et "marche" en test unitaire du sous-type, mais viole LSP.

// ISP respecté (interface fine) MAIS SRP violé (deux acteurs dans une classe)
interface PayrollCalculator { Money calculatePay(Employee e); }
class Employee implements PayrollCalculator {
    public Money calculatePay(Employee e) { /* règle demandée par la COMPTA */ ... }
    public Hours reportHours(Employee e) { /* règle demandée par les RH */ ... }
    // Une seule classe sert deux acteurs (compta + RH) -> SRP violé,
    // même si chaque interface exposée est bien segmentée.
}

// SRP respecté (une raison de changer) MAIS ISP violé (interface obèse)
interface Machine { void print(); void scan(); void fax(); void staple(); }
class SimplePrinter implements Machine {
    public void print() { ... }
    public void scan()   { throw new UnsupportedOperationException(); } // client forcé de dépendre de ce qu'il n'utilise pas
    public void fax()    { throw new UnsupportedOperationException(); }
    public void staple() { throw new UnsupportedOperationException(); }
}
